export function poseBodyLayerLabels(code='EN'){
 const i=Math.max(0,['EN','HU','DE','FR','ES','IT','PT','PL'].indexOf(code));return Object.fromEntries(Object.entries(bodyLayerWords).map(([k,v])=>[k,v.split('|')[i]]));
}
export function attachPoseBodyLayers({host,getLanguage=()=> 'EN',onChange=()=>{}}){
 const root=document.createElement('details');root.className='pose-body-controls';host.append(root);const words=[],fields={},config={skeleton:true,body:false,depth:false,bodyOpacity:45,depthOpacity:100},help=createPoseHelp(getLanguage);
 const t=()=>poseBodyLayerLabels(getLanguage()),word=(tag,key)=>{const n=document.createElement(tag);words.push([n,key]);return n;};root.append(word('summary','title'));
 const panel=document.createElement('div');panel.className='pose-body-fields';root.append(panel);
 for(const key of Object.keys(config)){
  const label=document.createElement('label'),input=document.createElement('input');input.type=typeof config[key]==='boolean'?'checkbox':'range';input.dataset.poseLayer=key;if(input.type==='range'){input.min=0;input.max=100;input.step=1;}
  label.append(word('span',key),input);panel.append(label);fields[key]=input;if(input.type==='range'){const out=document.createElement('output');label.append(out);input.layerOutput=out;}
  help.add(label,()=>t().hint,()=>t()[key]);input.addEventListener(input.type==='range'?'input':'change',()=>{config[key]=input.type==='checkbox'?input.checked:Math.max(0,Math.min(100,Number(input.value)||0));refresh();onChange();});
 }
 const note=document.createElement('details');note.className='pose-body-help';note.append(word('summary','help'),word('p','hint'));root.append(note);
 function refresh(){for(const [n,key]of words)n.textContent=t()[key];for(const [key,n]of Object.entries(fields)){n.setAttribute('aria-label',t()[key]);if(n.type==='checkbox')n.checked=config[key];else {n.value=String(config[key]);n.layerOutput.textContent=n.value+'%';}}help.refresh();}
 function restore(raw){if(!raw||typeof raw!=='object')return;for(const key of Object.keys(config)){if(typeof config[key]==='boolean'){if(typeof raw[key]==='boolean')config[key]=raw[key];}else if(typeof raw[key]==='number'&&Number.isFinite(raw[key]))config[key]=Math.max(0,Math.min(100,raw[key]));}refresh();}
 refresh();return {refresh,restore,root,get:()=>({...config})};
}
export function poseBodyCanvas(render,kind='body'){
 const canvas=document.createElement('canvas');canvas.width=render.width;canvas.height=render.height;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas unavailable');
 const image=ctx.createImageData(render.width,render.height);image.data.set(kind==='depth'?render.depthRGBA:render.rgba);ctx.putImageData(image,0,0);return canvas;
}
